"""Data models for coverage extraction results.

CoverageMetrics   — raw, format-agnostic numbers.
CoverageResult    — full extraction record with provenance for reproducibility.

coverage_source values
----------------------
  "codecov"              fetched from Codecov API
  "coveralls"            fetched from Coveralls API
  "repository_artifact"  parsed from a file found in the repository tree
  "local_execution"      generated by running tests locally
  "unavailable"          extraction failed or unsupported

execution_status values
-----------------------
  "success"      coverage data obtained
  "failed"       attempted, failed with an error
  "timeout"      local execution exceeded the time limit
  "unsupported"  language/build system not supported for local execution
  "unavailable"  no coverage information found at any priority level
"""
from dataclasses import asdict, dataclass
from datetime import datetime, timezone
from typing import Optional


@dataclass
class CoverageMetrics:
    """Raw coverage numbers — format-agnostic intermediate representation."""

    coverage_percent: Optional[float]
    lines_covered: Optional[int] = None
    lines_missed: Optional[int] = None
    branches_covered: Optional[int] = None
    branches_missed: Optional[int] = None


@dataclass
class CoverageResult:
    """Complete, reproducible coverage extraction record for one repository."""

    # Identity
    repository: str               # "{org}/{repo}"
    platform: str                 # "github" | "gitlab"
    commit_sha: Optional[str]
    default_branch: Optional[str]

    # Coverage metrics
    coverage_percent: Optional[float]
    coverage_lines_covered: Optional[int]
    coverage_lines_missed: Optional[int]
    coverage_branches_covered: Optional[int]
    coverage_branches_missed: Optional[int]

    # Provenance
    coverage_source: str
    coverage_provider: Optional[str]
    coverage_generation_method: Optional[str]
    coverage_collection_date: str

    # Reproducibility
    tool_used: Optional[str]
    execution_status: str
    language: Optional[str]
    build_system: Optional[str]

    # Error
    coverage_error: Optional[str]

    def to_dict(self) -> dict:
        return asdict(self)

    @classmethod
    def unavailable(
        cls,
        repository: str,
        platform: str,
        reason: str,
        commit_sha: Optional[str] = None,
        default_branch: Optional[str] = None,
        language: Optional[str] = None,
        build_system: Optional[str] = None,
        execution_status: str = "unavailable",
    ) -> "CoverageResult":
        """Convenience constructor for failed or unsupported extractions."""
        return cls(
            repository=repository,
            platform=platform,
            commit_sha=commit_sha,
            default_branch=default_branch,
            coverage_percent=None,
            coverage_lines_covered=None,
            coverage_lines_missed=None,
            coverage_branches_covered=None,
            coverage_branches_missed=None,
            coverage_source="unavailable",
            coverage_provider=None,
            coverage_generation_method=None,
            coverage_collection_date=datetime.now(timezone.utc).isoformat(),
            tool_used=None,
            execution_status=execution_status,
            language=language,
            build_system=build_system,
            coverage_error=reason,
        )

    @classmethod
    def from_metrics(
        cls,
        repository: str,
        platform: str,
        metrics: CoverageMetrics,
        *,
        coverage_source: str,
        coverage_provider: Optional[str],
        coverage_generation_method: Optional[str],
        coverage_collection_date: str,
        tool_used: Optional[str],
        commit_sha: Optional[str] = None,
        default_branch: Optional[str] = None,
        language: Optional[str] = None,
        build_system: Optional[str] = None,
    ) -> "CoverageResult":
        """Build a success result from a CoverageMetrics object."""
        return cls(
            repository=repository,
            platform=platform,
            commit_sha=commit_sha,
            default_branch=default_branch,
            coverage_percent=metrics.coverage_percent,
            coverage_lines_covered=metrics.lines_covered,
            coverage_lines_missed=metrics.lines_missed,
            coverage_branches_covered=metrics.branches_covered,
            coverage_branches_missed=metrics.branches_missed,
            coverage_source=coverage_source,
            coverage_provider=coverage_provider,
            coverage_generation_method=coverage_generation_method,
            coverage_collection_date=coverage_collection_date,
            tool_used=tool_used,
            execution_status="success",
            language=language,
            build_system=build_system,
            coverage_error=None,
        )
